 "content": "def transform(grid):
    """Copy the embedded 5-cell horizontal motif centered at each isolated clue."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Find the longest horizontal contiguous non-background run; this is the
    # exemplar motif. In these tasks the object has five cells.
    best = None
    for r, row in enumerate(g):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if best is None or c - start > best[2] - best[1]:
                best = (r, start, c)
    if best is None:
        return g
    mr, left, right = best
    motif = g[mr][left:right]
    center = left + (len(motif) - 1) // 2

    # Isolated non-background cells outside the exemplar mark motif centers.
    clues = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg:
                continue
            if r == mr and left <= c < right:
                continue
            # Markers are singletons, unlike contiguous cells of the exemplar.
            neighbors = ((r > 0 and g[r-1][c] != bg) or
                         (r+1 < h and g[r+1][c] != bg) or
                         (c > 0 and g[r][c-1] != bg) or
                         (c+1 < w and g[r][c+1] != bg))
            if not neighbors:
                clues.append((r, c))

    for r, c in clues:
        start = c - center
        for j, value in enumerate(motif):
            x = start + j
            if 0 <= x < w:
                g[r][x] = value
    return g

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
